          longDescription:'The Grade 10 Community Service Learning course follows the KICD Grade 10 CSL curriculum design strand by strand: Citizenship, Life Skills, Action Research and Social Entrepreneurship. Each strand opens with an overview and its learning outcomes, and every sub-strand has three lessons followed by a quiz, an assignment, a revision page and a summary. Lessons include learning outcomes and objectives, a key inquiry question, a teacher explanation, key-term cards, step-by-step examples, a Kenyan case study, a “Service in Action” community task, guided practice, independent, pair, group and digital activities, CBC competencies, values and PCIs, common mistakes, teacher tips, exam tips, interactive questions, practice exercises, homework, reflection, a glossary and a 10-question quiz with explanations.',
