    <div style="font-family: Arial, sans-serif; line-height: 1.8; color: #e8eef5;">
    <div style="background: linear-gradient(135deg, #173f27, #10233d); padding: 22px; border-radius: 14px; margin-bottom: 22px; border-left: 5px solid #66bb6a;">
    <p style="margin:0;color:#c8e6c9;font-size:13px;letter-spacing:1px;text-transform:uppercase;">Strand 1.0 Citizenship · Sub-strand 1.2 Community Needs</p>
    <p style="margin:2px 0 0 0;"><span style="background:#0f2a1a;border:1px solid #66bb6a;color:#c8e6c9;padding:2px 10px;border-radius:999px;font-size:12px;">Lesson</span> <span style="color:#dcedc8;font-size:13px;">⏱️ 40 min</span>
    </p>
    <h2 style="color:#c8e6c9;margin:8px 0 10px 0;">📘 Lesson 1.2.2: Mapping Community Resources</h2>
    <p style="font-size:16px;"><strong style="color:#fde68a;">Introduction:</strong> You will learn to see your community not only as a place with problems but also as a place full of resources (assets) — people, natural resources, places, organisations, money and culture — and to draw a community resource map.</p>
    <p><strong style="color:#fde68a;">Why does this matter?</strong> Every community has strengths. When you know what is already available, you can plan low-cost, realistic projects that use local resources and last longer.</p>
    <p style="margin-bottom:4px;"><strong style="color:#fde68a;">Where will you use this?</strong>
    </p>
    <div style="display:flex;flex-wrap:wrap;gap:8px;margin:8px 0;"><span style="background:#0b1a2e;border:1px solid #a5d6a7;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">🗺️ Project planning</span><span style="background:#0b1a2e;border:1px solid #a5d6a7;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">🏛️ County development</span><span style="background:#0b1a2e;border:1px solid #a5d6a7;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">🌱 Farming groups</span><span style="background:#0b1a2e;border:1px solid #a5d6a7;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">🏫 School–community partnerships</span><span style="background:#0b1a2e;border:1px solid #a5d6a7;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">🚑 Emergency planning</span><span style="background:#0b1a2e;border:1px solid #a5d6a7;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">💡 Social enterprise</span>
    </div>
    <div style="background:rgba(15,23,42,0.55);border-radius:10px;padding:12px 14px;margin-top:12px;">
    <p style="margin:0 0 4px 0;"><strong style="color:#c8e6c9;">🎯 Learning outcomes (CBC):</strong> By the end of the sub-strand, you should be able to:</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Categorise community needs.</li>
    <li>Map community resources for CSL activities.</li>
    <li>Explore stakeholders for partnership in CSL activities.</li>
    <li>Recognise the scale of community needs and resources.</li>
    </ul>
    <p style="margin:8px 0 4px 0;"><strong style="color:#c8e6c9;">🏁 Lesson objectives:</strong> By the end of this lesson, you should be able to:</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Explain asset (resource) mapping.</li>
    <li>Identify six types of community resources.</li>
    <li>Draw a community resource map with a key.</li>
    <li>Match resources to identified needs.</li>
    </ul>
    <p style="margin:8px 0 0 0;"><strong style="color:#c8e6c9;">❓ Key inquiry question:</strong> How can we determine needs to be addressed in the community?</p>
    <p style="margin:8px 0 0 0;"><strong style="color:#c8e6c9;">🧰 What you already know:</strong> Lesson 1.2.1 — identifying and categorising needs.</p>
    </div>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">👩🏾‍🏫 Teacher Explanation</h3>
    <p>There are two ways to look at a glass of water half full. One person says, “It is half empty — we need more.” Another says, “It is half full — let us use what we have well.” Communities are the same. A <strong>needs-based</strong> view sees only problems. An <strong>asset-based</strong> view also sees the skills, places and organisations already there.</p>
    <p><strong>Community resource mapping</strong> (also called asset mapping) is the process of identifying, locating and recording the resources available in a community that can be used to meet its needs.</p>
    <div style="background:#12301d;border-left:4px solid #66bb6a;padding:14px 16px;border-radius:9px;margin:14px 0;">
    <p style="margin:0 0 6px 0;color:#c8e6c9;font-weight:bold;">🗣️ In Simple Words</p>
    <div>Needs tell you <strong>what to fix</strong>. Resources tell you <strong>what to fix it with</strong>.</div>
    </div>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">📚 Key Terms</h3>
    <p>Read each term, its meaning and the community example. Then explain the term to a partner in your own words.</p>
    <div style="display:flex;flex-wrap:wrap;gap:12px;">
    <div style="flex:1 1 250px;background:#0b1a2e;border:1px solid #1f3a5a;border-top:3px solid #66bb6a;border-radius:10px;padding:12px 14px;">
    <p style="margin:0;font-size:18px;"><strong style="color:#fde68a;">Resource</strong>
    </p>
    <p style="margin:6px 0;">Anything that can be used to meet a need.</p>
    <p style="margin:6px 0 0 0;font-size:14px;color:#cbd5e1;">🏘️ <em>The community hall is a resource for meetings.</em>
    </p>
    </div>
    <div style="flex:1 1 250px;background:#0b1a2e;border:1px solid #1f3a5a;border-top:3px solid #66bb6a;border-radius:10px;padding:12px 14px;">
    <p style="margin:0;font-size:18px;"><strong style="color:#fde68a;">Asset</strong>
    </p>
    <p style="margin:6px 0;">A useful or valuable quality, person or thing.</p>
    <p style="margin:6px 0 0 0;font-size:14px;color:#cbd5e1;">🏘️ <em>Retired teachers are an asset to the village.</em>
    </p>
    </div>
    <div style="flex:1 1 250px;background:#0b1a2e;border:1px solid #1f3a5a;border-top:3px solid #66bb6a;border-radius:10px;padding:12px 14px;">
    <p style="margin:0;font-size:18px;"><strong style="color:#fde68a;">Human resources</strong>
    </p>
    <p style="margin:6px 0;">People and their skills, knowledge and time.</p>
    <p style="margin:6px 0 0 0;font-size:14px;color:#cbd5e1;">🏘️ <em>A local carpenter offered to train youths.</em>
    </p>
    </div>
    <div style="flex:1 1 250px;background:#0b1a2e;border:1px solid #1f3a5a;border-top:3px solid #66bb6a;border-radius:10px;padding:12px 14px;">
    <p style="margin:0;font-size:18px;"><strong style="color:#fde68a;">Natural resources</strong>
    </p>
    <p style="margin:6px 0;">Materials from nature.</p>
    <p style="margin:6px 0 0 0;font-size:14px;color:#cbd5e1;">🏘️ <em>The river, trees and soil are natural resources.</em>
    </p>
    </div>
    <div style="flex:1 1 250px;background:#0b1a2e;border:1px solid #1f3a5a;border-top:3px solid #66bb6a;border-radius:10px;padding:12px 14px;">
    <p style="margin:0;font-size:18px;"><strong style="color:#fde68a;">Map key (legend)</strong>
    </p>
    <p style="margin:6px 0;">A guide explaining symbols on a map.</p>
    <p style="margin:6px 0 0 0;font-size:14px;color:#cbd5e1;">🏘️ <em>In the key, a blue square stands for a water point.</em>
    </p>
    </div>
    <div style="flex:1 1 250px;background:#0b1a2e;border:1px solid #1f3a5a;border-top:3px solid #66bb6a;border-radius:10px;padding:12px 14px;">
    <p style="margin:0;font-size:18px;"><strong style="color:#fde68a;">Institution</strong>
    </p>
    <p style="margin:6px 0;">An established organisation such as a school, clinic or church.</p>
    <p style="margin:6px 0 0 0;font-size:14px;color:#cbd5e1;">🏘️ <em>The health centre is a key institution.</em>
    </p>
    </div>
    </div>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">1. Six Types of Community Resources</h3>
    <div style="overflow-x:auto;margin:12px 0;">
    <table style="width:100%;border-collapse:collapse;color:#f1f5f9;">
    <tr style="background:#334155;">
    <th style="padding:10px;border:1px solid #475569;text-align:left;">Type</th>
    <th style="padding:10px;border:1px solid #475569;text-align:left;">Examples</th>
    </tr>
    <tr>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Human</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Skills of residents (mechanics, tailors, nurses), youth energy, elders’ knowledge, volunteers</td>
    </tr>
    <tr style="background:#172033;">
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Natural</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Rivers, springs, land, trees, sunshine, soil, sand, stones</td>
    </tr>
    <tr>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Physical (infrastructure)</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Roads, halls, schools, markets, water points, playgrounds, mobile network</td>
    </tr>
    <tr style="background:#172033;">
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Financial</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Savings groups (chamas), SACCOs, county funds (e.g. ward bursaries), local businesses</td>
    </tr>
    <tr>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Social and institutional</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Churches, mosques, NGOs, youth groups, women’s groups, the chief’s office, clinics</td>
    </tr>
    <tr style="background:#172033;">
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Cultural</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Traditions, languages, songs, dances, local festivals, shared values</td>
    </tr>
    </table>
    </div>
    <div style="background:#062a2e;border-left:4px solid #14b8a6;padding:14px 16px;border-radius:9px;margin:14px 0;">
    <p style="margin:0 0 6px 0;color:#5eead4;font-weight:bold;">🌍 Real-Life Connection</p>
    <div>A savings group (chama) might lend money; a church might lend its hall; a retired nurse might train volunteers. Together these resources can power a CSL project at very low cost.</div>
    </div>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">2. Drawing a Community Resource Map</h3>
    <ol style="margin:6px 0;padding-left:22px;">
    <li>Decide the area to map (e.g. a 1 km radius around the school).</li>
    <li>Walk the area with a checklist; note each resource and where it is.</li>
    <li>Draw the main features first: roads, rivers, the school.</li>
    <li>Add resources using simple symbols (e.g. ✚ clinic, 💧 water point, ⛪ church).</li>
    <li>Add a <strong>title</strong>, a <strong>key (legend)</strong>, a <strong>north arrow</strong> and the <strong>date</strong>.</li>
    <li>Mark the needs you identified in red, so you can see which resources are near which needs.</li>
    <li>Check the map with community members and correct it.</li>
    </ol>
    <div style="background:#0b1a2e;border-left:4px solid #43a047;border-radius:9px;padding:16px;margin:16px 0;">
    <p style="margin:0 0 8px 0;color:#a5d6a7;font-weight:bold;">✏️ Step-by-Step Example 1: Matching needs to resources</p>
    <p style="margin:4px 0;"><strong style="color:#fde68a;">Task:</strong> Your map shows: a dark path (need), a youth group, the ward office, a hardware shop, and a church with a hall. Suggest how these resources could help meet the need.</p>
    <p style="margin:8px 0;color:#cbd5e1;font-style:italic;">🧠 <strong>How to think about it:</strong> Match each resource type to a part of the solution.</p>
    <div style="background:#132a45;border-radius:8px;padding:10px 12px;margin:8px 0;">
    <p style="margin:0;"><span style="display:inline-block;min-width:26px;height:26px;line-height:26px;text-align:center;border-radius:50%;background:#43a047;color:#0b1220;font-weight:bold;margin-right:8px;">1</span><strong style="color:#c8e6c9;">Step 1: Human/social</strong>
    </p>
    <div style="margin:6px 0 0 34px;">The youth group can clear bushes along the path.</div>
    </div>
    <div style="background:#132a45;border-radius:8px;padding:10px 12px;margin:8px 0;">
    <p style="margin:0;"><span style="display:inline-block;min-width:26px;height:26px;line-height:26px;text-align:center;border-radius:50%;background:#43a047;color:#0b1220;font-weight:bold;margin-right:8px;">2</span><strong style="color:#c8e6c9;">Step 2: Political/institutional</strong>
    </p>
    <div style="margin:6px 0 0 34px;">The ward office can be asked to install solar lights.</div>
    </div>
    <div style="background:#132a45;border-radius:8px;padding:10px 12px;margin:8px 0;">
    <p style="margin:0;"><span style="display:inline-block;min-width:26px;height:26px;line-height:26px;text-align:center;border-radius:50%;background:#43a047;color:#0b1220;font-weight:bold;margin-right:8px;">3</span><strong style="color:#c8e6c9;">Step 3: Financial/physical</strong>
    </p>
    <div style="margin:6px 0 0 34px;">The hardware shop might donate or discount tools.</div>
    </div>
    <div style="background:#132a45;border-radius:8px;padding:10px 12px;margin:8px 0;">
    <p style="margin:0;"><span style="display:inline-block;min-width:26px;height:26px;line-height:26px;text-align:center;border-radius:50%;background:#43a047;color:#0b1220;font-weight:bold;margin-right:8px;">4</span><strong style="color:#c8e6c9;">Step 4: Social</strong>
    </p>
    <div style="margin:6px 0 0 34px;">The church hall can host a community meeting to plan the work.</div>
    </div>
    <div style="background:#0f2a1a;border:1px solid #43a047;border-radius:8px;padding:10px 12px;margin-top:10px;"><strong style="color:#a5d6a7;">✅ Model answer:</strong> Youth group (labour), ward office (lighting), hardware shop (tools), church hall (meeting venue) — a low-cost, community-owned solution.</div>
    <p style="margin:8px 0 0 0;color:#6ee7b7;">🌟 <strong>Why this works:</strong> It shows how mapping resources turns a problem into a realistic plan.</p>
    </div>
    <div style="background:#2a2410;border-left:4px solid #f59e0b;padding:14px 16px;border-radius:9px;margin:14px 0;">
    <p style="margin:0 0 6px 0;color:#fcd34d;font-weight:bold;">💡 Teacher Tip</p>
    <div>Your map does not need to be artistic. It needs to be <strong>clear</strong>, <strong>accurate</strong> and <strong>checked</strong> with the people who live there.</div>
    </div>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">3. Practice: Classify the Resources</h3>
    <div style="background:#1e1b4b;border:1px solid #6366f1;border-radius:12px;padding:16px;margin:16px 0;">
    <p style="margin:0 0 6px 0;color:#c7d2fe;font-weight:bold;">🎯 Interactive Questions 1 <span style="font-weight:normal;color:#c5e1a5;font-size:14px;">— try first, then open the answer.</span>
    </p>
    <p style="margin:8px 0 2px 0;"><strong>1.</strong> Classify: a women’s chama.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">Financial (and social/institutional).</div>
    </details>
    <p style="margin:8px 0 2px 0;"><strong>2.</strong> Classify: a fundi who repairs bicycles.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">Human resource.</div>
    </details>
    <p style="margin:8px 0 2px 0;"><strong>3.</strong> Classify: a spring at the edge of the village.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">Natural resource.</div>
    </details>
    <p style="margin:8px 0 2px 0;"><strong>4.</strong> Why should a resource map be checked by community members?</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">To correct errors, add missing resources and build community ownership.</div>
    </details>
    </div>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;border-left:4px solid #f59e0b;">
    <h3 style="color:#a5d6a7;margin-top:0;">📰 Case Study</h3>
    <p><strong>From Problems to Assets in Kisumu Ndogo.</strong> A school CSL club first listed 20 problems in their estate and felt discouraged. Their teacher asked them to map assets instead. They found two retired teachers, a carpentry workshop, a women’s chama, a mosque with a big compound, three youth groups and a primary school with an empty classroom in the afternoons. Within a month, the retired teachers and club members started an afternoon homework club in the empty classroom, using benches made by the carpentry workshop.</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>How did asset mapping change the club’s attitude?</li>
    <li>Which resource types were used in the homework club?</li>
    <li>Why might this project last longer than one funded only from outside?</li>
    </ul>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;border-left:4px solid #66bb6a;">
    <h3 style="color:#a5d6a7;margin-top:0;">🤝 Service in Action: Community Connection</h3>
    <p>Draw a resource map of the area within about 500 metres of your school or home. Include at least eight resources from at least four types, a key, a north arrow and a title. Show it to one adult who lives in the area and add any resources they mention.</p>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">🧭 Guided Practice</h3>
    <p>Let us do these together. Read the task, use the hint, then compare your answer.</p>
    <div style="background:#0b1a2e;border-radius:9px;padding:10px 14px;margin:10px 0;">
    <p style="margin:0;"><strong style="color:#fde68a;">1.</strong> What is community resource (asset) mapping?</p>
    <p style="margin:4px 0;color:#cbd5e1;font-style:italic;">🪜 Hint: Find + locate + record.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">Identifying, locating and recording resources available in a community to meet its needs.</div>
    </details>
    </div>
    <div style="background:#0b1a2e;border-radius:9px;padding:10px 14px;margin:10px 0;">
    <p style="margin:0;"><strong style="color:#fde68a;">2.</strong> Give one example of a cultural resource.</p>
    <p style="margin:4px 0;color:#cbd5e1;font-style:italic;">🪜 Hint: Think traditions.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">E.g. traditional songs, local festivals, languages, shared values.</div>
    </details>
    </div>
    <div style="background:#0b1a2e;border-radius:9px;padding:10px 14px;margin:10px 0;">
    <p style="margin:0;"><strong style="color:#fde68a;">3.</strong> Name four things every map should have.</p>
    <p style="margin:4px 0;color:#cbd5e1;font-style:italic;">🪜 Hint: Remember Geography lessons.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">Title, key (legend), north arrow, date (and scale if possible).</div>
    </details>
    </div>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">🛠️ Learning Activities</h3>
    <div style="background:#1e1b4b;border-left:4px solid #818cf8;padding:14px 16px;border-radius:9px;margin:14px 0;">
    <p style="margin:0 0 6px 0;color:#c7d2fe;font-weight:bold;">🧍 Independent Activity</p>
    <div>List three human resources in your family or neighbourhood (skills people have) that could support a CSL project.</div>
    </div>
    <div style="background:#1e1b4b;border-left:4px solid #818cf8;padding:14px 16px;border-radius:9px;margin:14px 0;">
    <p style="margin:0 0 6px 0;color:#c7d2fe;font-weight:bold;">👥 Pair Activity</p>
    <div>Swap resource maps with a partner. Check each other’s map for title, key, north arrow and clarity.</div>
    </div>
    <div style="background:#1e1b4b;border-left:4px solid #818cf8;padding:14px 16px;border-radius:9px;margin:14px 0;">
    <p style="margin:0 0 6px 0;color:#c7d2fe;font-weight:bold;">👨‍👩‍👧‍👦 Group Activity</p>
    <div>Combine individual maps into one large class resource map on chart paper. Mark needs in red and resources in green.</div>
    </div>
    <div style="background:#0f2a1a;border-left:4px solid #22c55e;padding:14px 16px;border-radius:9px;margin:14px 0;">
    <p style="margin:0 0 6px 0;color:#86efac;font-weight:bold;">💻 Digital Activity</p>
    <div>Use a free online map (e.g. OpenStreetMap or Google My Maps) to pin five community resources near your school.</div>
    </div>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">🏋️ Practice Exercises</h3>
    <p>Work in your exercise book. Start with the easy questions and move up. Open each answer only after trying.</p>
    <div style="background:#0b1a2e;border-radius:10px;padding:12px 14px;margin:12px 0;border-top:3px solid #86efac;">
    <p style="margin:0 0 6px 0;color:#86efac;font-weight:bold;">Easy</p>
    <p style="margin:8px 0 2px 0;"><strong>Q1.</strong> What is a resource?</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">Anything that can be used to meet a need.</div>
    </details>
    <p style="margin:8px 0 2px 0;"><strong>Q2.</strong> List the six types of community resources.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">Human, natural, physical, financial, social/institutional, cultural.</div>
    </details>
    </div>
    <div style="background:#0b1a2e;border-radius:10px;padding:12px 14px;margin:12px 0;border-top:3px solid #fde68a;">
    <p style="margin:0 0 6px 0;color:#fde68a;font-weight:bold;">Medium</p>
    <p style="margin:8px 0 2px 0;"><strong>Q3.</strong> Differentiate a needs-based approach from an asset-based approach.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">Needs-based focuses on problems; asset-based also identifies existing strengths and resources to solve problems.</div>
    </details>
    <p style="margin:8px 0 2px 0;"><strong>Q4.</strong> Give two examples of financial resources in a community.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">E.g. chamas, SACCOs, local businesses, ward bursary funds.</div>
    </details>
    </div>
    <div style="background:#0b1a2e;border-radius:10px;padding:12px 14px;margin:12px 0;border-top:3px solid #fb923c;">
    <p style="margin:0 0 6px 0;color:#fb923c;font-weight:bold;">Challenging</p>
    <p style="margin:8px 0 2px 0;"><strong>Q5.</strong> Explain how using local resources can make a CSL project sustainable.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">The community owns and can maintain the resources, costs are low, and the project does not depend on outsiders.</div>
    </details>
    </div>
    <div style="background:#0b1a2e;border-radius:10px;padding:12px 14px;margin:12px 0;border-top:3px solid #5eead4;">
    <p style="margin:0 0 6px 0;color:#5eead4;font-weight:bold;">Real Life</p>
    <p style="margin:8px 0 2px 0;"><strong>Q6.</strong> A primary school has no clean water. Using resource mapping, suggest three local resources that might help.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">E.g. a nearby spring (natural), a plumber resident (human), the school roof for rain harvesting (physical), a chama for funds (financial).</div>
    </details>
    </div>
    <div style="background:#0b1a2e;border-radius:10px;padding:12px 14px;margin:12px 0;border-top:3px solid #e2e8f0;">
    <p style="margin:0 0 6px 0;color:#e2e8f0;font-weight:bold;">Mixed Revision</p>
    <p style="margin:8px 0 2px 0;"><strong>Q7.</strong> From lesson 1.2.1: categorise the need “no clean water at a school”.</p>
    <details style="margin:4px 0 10px 0;">
    <summary style="cursor:pointer;color:#c5e1a5;">👉 Show answer</summary>
    <div style="background:#0b1a2e;border-radius:8px;padding:8px 12px;margin-top:6px;color:#c8e6c9;">Social (health) and environmental.</div>
    </details>
    </div>
    </div>
    <div style="background:#173f27;padding:20px;border-radius:12px;border:1px solid #66bb6a;margin-bottom:20px;">
    <h3 style="color:#c8e6c9;margin-top:0;">🧠 Lesson Summary</h3>
    <p>Community resource mapping identifies, locates and records the resources a community already has — human, natural, physical, financial, social/institutional and cultural. A resource map with a title, key and north arrow, checked by residents, helps match resources to needs and design low-cost, sustainable projects.</p>
    <h4 style="color:#c5e1a5;margin:16px 0 6px 0;">🗒️ Revision notes</h4>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Asset-based view: see strengths as well as problems.</li>
    <li>Six resource types.</li>
    <li>Map: title, key, north arrow, date.</li>
    <li>Match resources to needs.</li>
    </ul>
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:12px;margin-bottom:20px;">
    <div style="flex:1 1 260px;background:#0c2a1f;border-left:4px solid #10b981;border-radius:10px;padding:12px 14px;">
    <p style="margin:0 0 6px 0;font-weight:bold;color:#f1f5f9;">📌 Remember Box</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>People are the most important resource.</li>
    <li>Check maps with residents.</li>
    <li>Mark needs and resources in different colours.</li>
    </ul>
    </div>
    <div style="flex:1 1 260px;background:#2a1215;border-left:4px solid #ef4444;border-radius:10px;padding:12px 14px;">
    <p style="margin:0 0 6px 0;font-weight:bold;color:#f1f5f9;">⚠️ Common Mistakes</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Seeing a community only as a list of problems.</li>
    <li>Maps without a key.</li>
    <li>Ignoring cultural resources.</li>
    </ul>
    </div>
    <div style="flex:1 1 260px;background:#2a2410;border-left:4px solid #f59e0b;border-radius:10px;padding:12px 14px;">
    <p style="margin:0 0 6px 0;font-weight:bold;color:#f1f5f9;">💡 Teacher Tips</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Use simple symbols.</li>
    <li>Ask “Who else can help?” at every step.</li>
    <li>Keep your map in your portfolio.</li>
    </ul>
    </div>
    <div style="flex:1 1 260px;background:#10233d;border-left:4px solid #43a047;border-radius:10px;padding:12px 14px;">
    <p style="margin:0 0 6px 0;font-weight:bold;color:#f1f5f9;">📝 Exam Tips</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Name the resource type and give an example.</li>
    <li>Explain how a resource can meet a specific need.</li>
    </ul>
    </div>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">🌍 Competencies, Values and PCIs</h3>
    <div style="overflow-x:auto;margin:12px 0;">
    <table style="width:100%;border-collapse:collapse;color:#f1f5f9;">
    <tr style="background:#334155;">
    <th style="padding:10px;border:1px solid #475569;text-align:left;">CBC core competency</th>
    <th style="padding:10px;border:1px solid #475569;text-align:left;">How this lesson builds it</th>
    </tr>
    <tr>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;"><strong style="color:#5eead4;">Communication and collaboration</strong>
    </td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Mapping with community members.</td>
    </tr>
    <tr style="background:#172033;">
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;"><strong style="color:#5eead4;">Digital literacy</strong>
    </td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Online mapping tools.</td>
    </tr>
    <tr>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;"><strong style="color:#5eead4;">Creativity</strong>
    </td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Designing clear maps.</td>
    </tr>
    </table>
    </div>
    <h4 style="color:#c5e1a5;margin:16px 0 6px 0;">💚 Values</h4>
    <div style="display:flex;flex-wrap:wrap;gap:8px;margin:8px 0;"><span style="background:#0b1a2e;border:1px solid #10b981;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">Unity</span><span style="background:#0b1a2e;border:1px solid #10b981;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">Respect</span>
    </div>
    <h4 style="color:#c5e1a5;margin:16px 0 6px 0;">🧩 Pertinent and Contemporary Issues (PCIs)</h4>
    <div style="display:flex;flex-wrap:wrap;gap:8px;margin:8px 0;"><span style="background:#0b1a2e;border:1px solid #f59e0b;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">Civic responsibility</span><span style="background:#0b1a2e;border:1px solid #f59e0b;color:#e2e8f0;padding:4px 12px;border-radius:999px;font-size:14px;">Social cohesion</span>
    </div>
    <p><strong style="color:#5eead4;">Real-life use:</strong> Planners, disaster-response teams and businesses use resource maps to make quick, effective decisions.</p>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">🏠 Homework</h3>
    <ol style="margin:6px 0;padding-left:22px;">
    <li>Complete your resource map and write five sentences explaining how resources could meet needs you found in lesson 1.2.1.</li>
    <li>Interview a local leader about the most useful resources in the community.</li>
    </ol>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">🪞 Reflection</h3>
    <p>Answer honestly in your journal:</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Did mapping change how I see my community?</li>
    <li>Which resource surprised me most?</li>
    </ul>
    </div>
    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #1f3a5a;">
    <h3 style="color:#a5d6a7;margin-top:0;">📖 Glossary</h3>
    <div style="overflow-x:auto;margin:12px 0;">
    <table style="width:100%;border-collapse:collapse;color:#f1f5f9;">
    <tr style="background:#334155;">
    <th style="padding:10px;border:1px solid #475569;text-align:left;">Term</th>
    <th style="padding:10px;border:1px solid #475569;text-align:left;">Meaning</th>
    </tr>
    <tr>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;"><strong style="color:#fde68a;">Resource</strong>
    </td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Anything used to meet a need.</td>
    </tr>
    <tr style="background:#172033;">
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;"><strong style="color:#fde68a;">Asset mapping</strong>
    </td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Identifying and locating community resources.</td>
    </tr>
    <tr>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;"><strong style="color:#fde68a;">Map key</strong>
    </td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Explanation of map symbols.</td>
    </tr>
    <tr style="background:#172033;">
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;"><strong style="color:#fde68a;">Institution</strong>
    </td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">An established organisation.</td>
    </tr>
    </table>
    </div>
    </div>
    <div style="background:#0f2a1a;padding:20px;border-radius:12px;border:1px solid #43a047;margin-bottom:20px;">
    <h3 style="color:#a5d6a7;margin-top:0;">✅ Self-Check</h3>
    <p>Tick ☑ only if you can do it without looking at the notes.</p>
    <p style="margin:6px 0;">☐ I can explain resource mapping.</p>
    <p style="margin:6px 0;">☐ I can identify six types of resources.</p>
    <p style="margin:6px 0;">☐ I can draw a resource map.</p>
    <p style="margin:6px 0;">☐ I can match resources to needs.</p>
    </div>
    </div>
